INSERT INTO feature VALUES('footprint-separation','effects','Separate footprints at a fork','capabilities','partial','uncommon','mainstream languages','A fork''s two halves run as peers, so they share a host interface only when every operation either half may perform on it only reads: each half''s footprint is read off the types of the names it mentions, a held capability at its authority, a returner''s row at each interface it names, whole, and an operation performed by name, and a fork whose halves share an interface one of them may change is refused FootprintsOverlap.','core-term core-checker','corpus/ledger/features/footprint-separation.gandr corpus/ledger/diagnostics/FootprintsOverlap.gandr','corpus/ledger/features/footprint-separation.gandr','#2878 #2879');
